contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address caller, uint amount) public payable {
        require(c.owner() != address(this));
        require(amount <= address(this).balance);

        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;

        (bool ok1, ) = address(c).call{value: amount}(abi.encodeWithSignature("withdraw(uint256)", amount));
        (bool ok2, ) = address(c).call{value: amount}(abi.encodeWithSignature("withdrawAll()"));
        (bool ok3, ) = address(c).call{value: amount}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", caller, amount, ""));

        assert(!ok1 && !ok2 && !ok3 && c.depositsCount() == depositsBefore && address(c).balance == cBalanceBefore);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address caller, uint amount, bytes memory data) public payable {
        require(amount <= address(this).balance);
        require(caller != c.owner());

        c.receive();
        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;
        uint ownerBalanceBefore = c.owner().balance;

        bool reverted1;
        try c.withdraw(amount) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        bool reverted2;
        try c.withdrawAll() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        bool reverted3;
        try c.sendMoney(caller, amount, data) {
            reverted3 = false;
        } catch {
            reverted3 = true;
        }

        assert(reverted1 && reverted2 && reverted3 && c.depositsCount() == depositsBefore && address(c).balance == cBalanceBefore && c.owner().balance == ownerBalanceBefore);
    }
}

