contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(msg.sender != address(0)); // msg.sender is this contract
        require(address(this).balance >= depositAmount);

        // Deposit into c to establish a starting balance.
        (bool depositSuccess, ) = address(c).call{value: depositAmount}("");
        require(depositSuccess);

        // Pre-state
        uint beforeBalance = address(c).balance;
        require(beforeBalance >= depositAmount);
        uint beforeOwnerBalance = c.owner().balance;

        // Action
        c.withdrawAll();

        // Post-state assertion: contract balance is zero, owner gained the entire prior balance.
        assert(address(c).balance == 0 && c.owner().balance >= beforeOwnerBalance + beforeBalance);
    }

    receive() external payable {}
}

