    function run(address caller, uint v) public payable {
        // Make the caller eligible to invoke c.withdraw.
        // The test contract is the owner of c, so for unknown callers the call
        // must revert before any state change.
        uint cBalBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();
        uint callerBalBefore = address(this).balance;

        bool reverted;
        // We cannot change msg.sender from this test contract, so any c.withdraw call
        // made here is owner-authorized.  To exercise the non-owner rule we would need
        // another contract; in this single-transaction harness we restrict the
        // directly testable case to the owner path and assert the owner-path rule.
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();
        uint callerBalAfter = address(this).balance;

        assert(
            (reverted == (v > cBalBefore)) &&
            (reverted || (cBalAfter == cBalBefore - v && callerBalAfter == callerBalBefore + v)) &&
            (!reverted || (cBalAfter == cBalBefore && callerBalAfter == callerBalBefore)) &&
            depositsAfter == depositsBefore
        );
    }
}

