        require(address(this).balance >= value);
        require(target != address(0));

        uint beforeC = address(c).balance;
        uint beforeD = c.depositsCount();
        address beforeO = c.owner();
        uint beforeT = target.balance;

        c.sendMoney(target, value, data);

        uint afterC = address(c).balance;
        uint afterD = c.depositsCount();
        address afterO = c.owner();
        uint afterT = target.balance;

        // Only assert when the target is an EOA (not a contract) to avoid reentrant side effects
        if (target.code.length == 0) {
            assert(afterC == beforeC - value && afterT == beforeT + value && afterD == beforeD && afterO == beforeO);
        } else {
            assert(afterD == beforeD && afterO == beforeO);
        }
    }

    receive() external payable {}
}

